function CltProduce:GetCltMaterialInfo()
	return CltProduce.MaterialTbl
end
function CltProduce:ValueInTable(val,tbl)
	if val and tbl and type(tbl) == --[[!AUTO_44]]"table" then
		for k,v in pairs(tbl) do
			if v == val then
				return true
			end
		end
	end
	return false
end

function CltProduce:GetCltProduceInput(clt_type)
	if CltProduce[clt_type] then
		return CltProduce[clt_type].Input
	end
end

--[[item_tbl为数组,每个项中为: ID,Quality,Part,Level,Type,DefendID,Prof,Bind
    返回值类型: 特殊ID(-1为不显示,0为显示问号,>0指定装备ID)
				品质
				部位mask
				职业mask
				绑定状态

				icon
                tip描述
--]]
function CltProduce:GetCltProduceInfo(clt_type,item_num,item_tbl)

		if CltProduce[clt_type] and CltProduce[clt_type].Produce then
			return CltProduce[clt_type].Produce(item_num,item_tbl,CltProduce[clt_type])
		end
		return CltProduce:FormatReturn(0,0,0,0,false,--[[!AUTO_45]]"不知啥東西")
end

function  CltProduce:GetIocn(quality,part,prof,bind)
	return 4780
end

function CltProduce:FormatReturn(flag,quality,part,prof,bind,tip)
	return flag,quality,part,prof,bind,CltProduce:GetIocn(quality,part,prof,bind),tip
end

