	--返回值类型: 特殊ID(-1为不显示,0为显示问号,>0指定装备ID),tip描述
	Produce = function (item_num, item_tbl)
		if item_num > 1 then
			local max_level = item_tbl[1].Level
			local min_level = item_tbl[1].Level
			for i = 2 , item_num do
				if item_tbl[i].Level > max_level then
					max_level = item_tbl[i].Level
				end
				if item_tbl[i].Level < min_level then
					min_level = item_tbl[i].Level
				end
			end					--[[得到最大装备等级和最小装备等级]]--
			if max_level - min_level < 3 then		--[[比较装备等级差]]--
				return CltProduce:FormatReturn(0 ,0,0,0,false,--[[!AUTO_46]]"3-5件相差1品內的任意裝備=1件新的任意裝備")
			else
				return CltProduce:FormatReturn(-1,0,0,0,false,--[[!AUTO_47]]"合成原料品級差不能超過1品。")
			end
		else
			return CltProduce:FormatReturn(-1,0,0,0,false,--[[!AUTO_48]]"放入裝備數量不足")
		end
	end
}
