--[[宝石合成]]-------------------------------------------------------------

--获得排序后的新table
--把所需条件转化为: {item,gem1,2,gem2,1,newgem,"text"} => {item,gem1,gem1,gem2}
function CltProduce:gemComposeGetSortTable(inputTable,newTable,startIndex,tableNum)
	local count = 0
	local newIndex = 2  --宝石的起始位置为2
	local modvalue = 0
	local num = 0
	--把道具放入第一个

	newTable[1] = inputTable[1]
	for i=2,tableNum do
		count = i+startIndex-1
		modvalue = count % 2
		if modvalue == 0 then	--解析gemid
			newTable[newIndex] = inputTable[count]
			newIndex = newIndex + 1
		else					--解析gem个数
			num = inputTable[count]
			local content = inputTable[count - 1]
			for k = 1, num-1 do
				newTable[newIndex] = content
				newIndex = newIndex + 1
			end
		end
	end
	--排序
	table.sort(newTable)
end


--宝石合成初始化

function CltProduce:gemComposeInit( clt_type )

	if CltProduce[clt_type] and CltProduce[clt_type].Input and CltProduce[clt_type].InputCompare then
		local number = table.maxn(CltProduce[clt_type].Input)
		for i =1 ,number do

			local tableNum = table.maxn(CltProduce[clt_type].Input[i])
			--LogPrint("ProduceInit1: "..clt_type.." number".. i .." tablenum:"..tableNum)
			CltProduce[clt_type].InputCompare[i] = {}
			CltProduce:gemComposeGetSortTable(CltProduce[clt_type].Input[i],CltProduce[clt_type].InputCompare[i],1,tableNum-2)
			--temp
			local str = --[[!AUTO_79]]"\ntable:"..table.maxn(CltProduce[clt_type].InputCompare[i])..--[[!AUTO_80]]"\n"
			for k = 1,table.maxn(CltProduce[clt_type].InputCompare[i]) do
				str = str..--[[!AUTO_81]]","..CltProduce[clt_type].InputCompare[i][k]
			end
			LogPrint(str)
		end
	end


end

function CltProduce:gemComposeCompareTable( table1, table2)
	local isEqual = false
	local count1 = table.maxn(table1)
	local count2 = table.maxn(table2)
	if count1 == count2 and count1 > 0 then
		isEqual = true
		for i = 1,count1 do
			if table1[i] ~= table2[i] then
				isEqual = false
				return isEqual
			end
		end
	end

	return isEqual
end

