	--程序数据还原缓存，把所需条件转化为: {item,gem1,2,gem2,1,newgem,"text"} => {item,gem1,gem1,gem2}
	InputCompare = {},

	Produce = function (item_num, item_tbl,this)
	    --temp
		LogPrint(string.format(--[[!AUTO_236]]"produce:%d\n",item_num))

		local new_Bind = false
		local gemTable = {}
		local index = 0
		--判断是否绑定物，把输入gem排序转换为比较表格式
		for i = 1 ,item_num do
			if item_tbl[i].Bind == true then
				new_Bind = true
			end
			gemTable[i] = item_tbl[i].ID
		end
		table.sort(gemTable)

		--temp
		local str = --[[!AUTO_237]]"\ngemtable:"..table.maxn(gemTable)..--[[!AUTO_238]]"\n"
		for k = 1,table.maxn(gemTable) do
				str = str..--[[!AUTO_239]]","..gemTable[k]
		end
		LogPrint(str)

		--比较缓存表，找出元素一样的表

		if this then
			for i = 1, table.maxn(this.InputCompare) do
				local isEqual = CltProduce:gemComposeCompareTable( gemTable, this.InputCompare[i])
				if isEqual then
					index = i
					break
				end
			end
		end

		if index > 0 then

			local count = table.maxn(this.Input[index])
			 --temp
			LogPrint(string.format(--[[!AUTO_240]]"bingoIndex:%d ,id: %d\n",index,this.Input[index][count-1]))
			return CltProduce:FormatReturn( this.Input[index][count-1],-1,-1,-1,new_Bind,this.Input[index][count])
		end

		return 	 CltProduce:FormatReturn(-1,0,0,0,false,--[[!AUTO_241]]"不能合成。")
	end
}



